style.css:
/* Once Upon a Marvel — Disney.com */

:root {
  /* puedes cambiar estos tonos */
  --my-cream: #fff8eb;
  --my-gold: #c5a45e;
  --my-pink: #e8c6c6;
  --my-red: #a92d35;
  --my-brown: #594533;
}

/* fondo de cuento */
body {
  background-color: var(--my-cream) !important;
  color: var(--my-brown) !important;
  font-family: Georgia, serif !important;
}

/* títulos elegantes */
h1, h2, h3, h4 {
  color: var(--my-gold) !important;
  font-family: Georgia, serif !important;
  text-shadow: 0 0 8px rgba(197, 164, 94, 0.35) !important;
}

/* enlaces dorados */
a {
  color: var(--my-gold) !important;
  text-decoration-color: var(--my-pink) !important;
  text-underline-offset: 4px !important;
}

/* botones de cuento */
button {
  border-radius: 18px !important;
  border: 1px solid var(--my-gold) !important;
  font-family: Georgia, serif !important;
}

/* guiño a Marvel */
button:hover {
  box-shadow: 0 0 12px rgba(169, 45, 53, 0.35) !important;
}

/* imágenes delicadas */
img {
  border-radius: 10px !important;
}

/* selección dorada */
::selection {
  background: var(--my-gold) !important;
  color: white !important;
}
